// ═══════ 2. HELPER FUNCTIONS (from @sabaki/boardmatcher) ═════════════

var mod=function(x,m){return((x%m)+m)%m}
var hasVertex=function(v,w,h){return v[0]>=0&&v[1]>=0&&v[0]<w&&v[1]<h}
var getNeighbors=function(v,w,h){return[[v[0]-1,v[1]],[v[0]+1,v[1]],[v[0],v[1]-1],[v[0],v[1]+1]].filter(function(n){return hasVertex(n,w,h)})}
var getSymmetries=function(v){return[[v[0],v[1]],[-v[0],v[1]],[v[0],-v[1]],[-v[0],-v[1]],[v[1],v[0]],[-v[1],v[0]],[v[1],-v[0]],[-v[1],-v[0]]]}
var getBoardSymmetries=function(v,w,h){var mx=w-1,my=h-1;return getSymmetries(v).map(function(s){return[mod(s[0],mx),mod(s[1],my)]}).filter(function(s){return hasVertex(s,w,h)})}
var getUnnamedHoshis=function(w,h){if(Math.min(w,h)<=7)return[];var nx=w>=13?3:2,ny=h>=13?3:2,fx=w-nx-1,fy=h-ny-1,mx=(w-1)/2,my=(h-1)/2,r=[];if(w%2!==0)r.push([mx,ny],[mx,fy]);if(h%2!==0)r.push([nx,my],[fx,my]);return r}
var equals=function(v){return function(w){return w[0]===v[0]&&w[1]===v[1]}}

var getPseudoLibertyCount=function(v,data,visited,result){
  if(!visited)visited=[];if(!result)result=[]
  var h=data.length,w=h===0?0:data[0].length,neighbors=getNeighbors(v,w,h),sign=data[v[1]][v[0]]
  visited.push(v)
  for(var i=0;i<neighbors.length;i++){
    var nx=neighbors[i][0],ny=neighbors[i][1]
    if(result.length>=3)break
    if(data[ny][nx]===-sign||visited.some(equals([nx,ny])))continue
    if(data[ny][nx]===0&&!result.some(equals([nx,ny]))){result.push([nx,ny]);continue}
    getPseudoLibertyCount([nx,ny],data,visited,result)
  }
  return result.length
}

// ═══════ 3. PATTERN MATCHING (from @sabaki/boardmatcher) ═══════════

var matchShape=function*(data,anchor,pattern){
  var h=data.length,w=h===0?0:data[0].length
  if(!hasVertex(anchor,w,h))return
  if(pattern.size!=null&&(w!==h||w!==+pattern.size))return
  var x=anchor[0],y=anchor[1],sign=data[y][x]
  if(sign===0)return
  var equalsVertex=equals(anchor)
  for(var ai=0;ai<(pattern.anchors||[]).length;ai++){
    var a=pattern.anchors[ai],ax=a[0][0],ay=a[0][1],as=a[1]
    if(pattern.type==='corner'&&!getBoardSymmetries([ax,ay],w,h).some(equalsVertex))continue
    var hypotheses=[true,true,true,true,true,true,true,true]
    for(var vi=0;vi<pattern.vertices.length;vi++){
      var pv=pattern.vertices[vi],vx=pv[0][0],vy=pv[0][1],vs=pv[1],diff=[vx-ax,vy-ay],symm=getSymmetries(diff)
      for(var k=0;k<symm.length;k++){
        if(!hypotheses[k])continue
        var wx=x+symm[k][0],wy=y+symm[k][1]
        if(!hasVertex([wx,wy],w,h)||data[wy][wx]!==vs*sign*as)hypotheses[k]=false
      }
      if(!hypotheses.some(function(h){return h}))break
    }
    for(var i=0;i<hypotheses.length;i++){
      if(!hypotheses[i])continue
      var transform=function(p){var s=getSymmetries([p[0]-ax,p[1]-ay])[i];return[anchor[0]+s[0],anchor[1]+s[1]]}
      yield{
        symmetryIndex:i,invert:sign!==as,
        anchors:pattern.anchors.map(function(p){return transform(p[0])}),
        vertices:pattern.vertices.map(function(p){return transform(p[0])})
      }
    }
  }
}

var findPatternInMove=function(data,sign,vertex,library){
  var h=data.length,w=h===0?0:data[0].length
  var isPass=sign===0||vertex==null||!hasVertex(vertex,w,h)
  var dummy=function(name,url){
    return{pattern:{name:name,url:url||null,anchors:isPass?[]:[[vertex,sign]],vertices:[]},match:{symmetryIndex:0,invert:false,anchors:isPass?[]:[vertex],vertices:[]}}
  }
  if(isPass)return dummy('Pass','https://senseis.xmp.net/?Pass')
  var x=vertex[0],y=vertex[1]
  if(data[y][x]!==0)return null
  if(!library)library=SHAPE_PATTERNS.concat(CORNER_PATTERNS)
  var neighbors=getNeighbors(vertex,w,h)

  for(var i=0;i<neighbors.length;i++){
    var nx=neighbors[i][0],ny=neighbors[i][1]
    if(data[ny][nx]!==-sign)continue
    var lc=getPseudoLibertyCount([nx,ny],data)
    if(lc===1)return dummy('Take')
    if(lc===2)return dummy('Atari','https://senseis.xmp.net/?Atari')
  }

  var nextData=data.map(function(row,j){return j!==y?row:row.map(function(s,i){return i!==x?s:sign})})
  if(getPseudoLibertyCount(vertex,nextData)===0)return dummy('Suicide','https://senseis.xmp.net/?Suicide')

  var friendlies=neighbors.filter(function(n){return data[n[1]][n[0]]===sign})
  if(friendlies.length===neighbors.length)return dummy('Fill')
  if(friendlies.length>=2)return dummy('Connect')

  for(var pi=0;pi<library.length;pi++){
    var iter=matchShape(nextData,vertex,library[pi])
    var result=iter.next()
    if(!result.done)return{pattern:library[pi],match:result.value}
  }

  if(equals([(w-1)/2,(h-1)/2])(vertex))return dummy('Tengen','https://senseis.xmp.net/?Tengen')
  if(getUnnamedHoshis(w,h).some(equals(vertex)))return dummy('Hoshi','https://senseis.xmp.net/?StarPoint')

  return null
}

// ═════════════════════════════════════════════════════════════════════
// 4. UNIFIED TERM HIGHLIGHT SYSTEM
//    One object. One place. Blue + green highlights.
//    All behavior — detect, store, sync, clear, draw — lives here.
// ═════════════════════════════════════════════════════════════════════

var _termVisible = false;

var _termHL = {
  blue: [],
  green: [],
  name: '',
  url: null,
  _active: false,

  set: function(blue, green, name, url) {
    this.blue = blue || [];
    this.green = green || [];
    this.name = name || '';
    this.url = url || null;
  },

  clear: function() {
    this.blue = [];
    this.green = [];
    this.name = '';
    this.url = null;
    this._active = false;
    window._highlightedCells = [];
    window._responseVertices = [];
  },

  show: function() {
    if (this.blue.length === 0 && this.green.length === 0) return;
    this._active = true;
    window._highlightedCells = this.blue;
    window._responseVertices = this.green;
    if (typeof drawBoard === 'function') drawBoard();
  },

  hide: function() {
    this._active = false;
    window._highlightedCells = [];
    window._responseVertices = [];
    if (typeof drawBoard === 'function') drawBoard();
  },

  isAtari: function() {
    return this.name.indexOf('Atari') !== -1;
  },

  drawBottom: function(ctx, PADDING, CELL_SIZE) {
    if (!this._active) return;

    if (this.blue.length > 0) {
      var unique = [];
      var seen = {};
      for (var i = 0; i < this.blue.length; i++) {
        var v = this.blue[i];
        var key = v[0] + ',' + v[1];
        if (!seen[key]) { seen[key] = true; unique.push(v); }
      }
      if (unique.length === 2) {
        var c1 = getVisualCoords(unique[0][0], unique[0][1], PADDING, CELL_SIZE);
        var c2 = getVisualCoords(unique[1][0], unique[1][1], PADDING, CELL_SIZE);
        var SR = CELL_SIZE * 0.47;
        var CR = SR * 1.20;
        var RH = CR * 0.70;
        ctx.save();
        var dx = c2.cx - c1.cx, dy = c2.cy - c1.cy;
        var dist = Math.sqrt(dx*dx + dy*dy);
        var angle = Math.atan2(dy, dx);
        ctx.translate(c1.cx, c1.cy);
        ctx.rotate(angle);
        ctx.beginPath();
        ctx.rect(0, -RH, dist, RH * 2);
        ctx.fillStyle = 'rgba(0, 130, 240, 0.4)';
        ctx.fill();
        ctx.strokeStyle = '#0082F0';
        ctx.lineWidth = 1.5;
        ctx.setLineDash([3.5, 1.5]);
        ctx.beginPath(); ctx.moveTo(0, -RH); ctx.lineTo(dist, -RH); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(0, RH); ctx.lineTo(dist, RH); ctx.stroke();
        ctx.restore();
      }
    }

    if (this.green.length > 0) {
      var uniqueG = [];
      var seenG = {};
      for (var j = 0; j < this.green.length; j++) {
        var g = this.green[j];
        var gkey = g[0] + ',' + g[1];
        if (!seenG[gkey]) { seenG[gkey] = true; uniqueG.push(g); }
      }
      if (uniqueG.length === 2) {
        var gc1 = getVisualCoords(uniqueG[0][0], uniqueG[0][1], PADDING, CELL_SIZE);
        var gc2 = getVisualCoords(uniqueG[1][0], uniqueG[1][1], PADDING, CELL_SIZE);
        var GSR = CELL_SIZE * 0.47;
        var GCR = GSR * 1.20;
        var GRH = GCR * 0.70;
        ctx.save();
        var gdx = gc2.cx - gc1.cx, gdy = gc2.cy - gc1.cy;
        var gdist = Math.sqrt(gdx*gdx + gdy*gdy);
        var gangle = Math.atan2(gdy, gdx);
        ctx.translate(gc1.cx, gc1.cy);
        ctx.rotate(gangle);
        ctx.beginPath();
        ctx.rect(0, -GRH, gdist, GRH * 2);
        ctx.fillStyle = 'rgba(34, 197, 94, 0.4)';
        ctx.fill();
        ctx.strokeStyle = '#22c55e';
        ctx.lineWidth = 1.5;
        ctx.setLineDash([3.5, 1.5]);
        ctx.beginPath(); ctx.moveTo(0, -GRH); ctx.lineTo(gdist, -GRH); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(0, GRH); ctx.lineTo(gdist, GRH); ctx.stroke();
        ctx.restore();
      }
    }
  },

  drawTop: function(ctx, PADDING, CELL_SIZE) {
    if (!this._active) return;

    if (this.blue.length > 0) {
      var seen = {};
      for (var i = 0; i < this.blue.length; i++) {
        var v = this.blue[i];
        var key = v[0] + ',' + v[1];
        if (seen[key]) continue;
        seen[key] = true;
        var co = getVisualCoords(v[0], v[1], PADDING, CELL_SIZE);
        var SR = CELL_SIZE * 0.47;
        var CR = SR * 1.20;
        ctx.save();
        ctx.beginPath();
        ctx.arc(co.cx, co.cy, CR, 0, Math.PI * 2);
        ctx.strokeStyle = '#0082F0';
        ctx.lineWidth = 3;
        ctx.setLineDash([]);
        ctx.stroke();
        ctx.restore();
      }
    }

    if (this.green.length > 0) {
      var seenG = {};
      for (var j = 0; j < this.green.length; j++) {
        var g = this.green[j];
        var gkey = g[0] + ',' + g[1];
        if (seenG[gkey]) continue;
        seenG[gkey] = true;
        var gco = getVisualCoords(g[0], g[1], PADDING, CELL_SIZE);
        var GSR = CELL_SIZE * 0.47;
        var GCR = GSR * 1.20;
        ctx.save();
        ctx.beginPath();
        ctx.arc(gco.cx, gco.cy, GCR, 0, Math.PI * 2);
        ctx.strokeStyle = '#22c55e';
        ctx.lineWidth = 3;
        ctx.setLineDash([]);
        ctx.stroke();
        ctx.restore();
      }
    }

    if (this.isAtari()) {
      var state = window.state;
      var _drawCautionTriangle = function(ctx, cx, cy, CELL_SIZE) {
        var STONE_R = CELL_SIZE * 0.47;
        var CIRCLE_F = STONE_R * 1.20;
        var DRAW_SIZE = CIRCLE_F * 0.55;
        var mapX = function(xVal) { return cx + (xVal - 50) / 100 * (DRAW_SIZE * 2); };
        var mapY = function(yVal) { return cy + (yVal - 58) / 100 * (DRAW_SIZE * 2); };
        var mapSize = function(val) { return val / 100 * (DRAW_SIZE * 2); };
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(mapX(50), mapY(8));
        ctx.lineTo(mapX(96), mapY(92));
        ctx.lineTo(mapX(4), mapY(92));
        ctx.closePath();
        ctx.fillStyle = '#D90429';
        ctx.fill();
        ctx.strokeStyle = '#D90429';
        ctx.lineWidth = mapSize(14);
        ctx.lineJoin = 'round';
        ctx.stroke();
        ctx.restore();
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(mapX(42), mapY(40));
        ctx.bezierCurveTo(mapX(42), mapY(30), mapX(58), mapY(30), mapX(58), mapY(40));
        ctx.lineTo(mapX(53), mapY(65));
        ctx.bezierCurveTo(mapX(53), mapY(67), mapX(47), mapY(67), mapX(47), mapY(65));
        ctx.closePath();
        ctx.fillStyle = '#ffffff';
        ctx.fill();
        ctx.restore();
        ctx.save();
        ctx.beginPath();
        ctx.arc(mapX(50), mapY(79), mapSize(8), 0, Math.PI * 2);
        ctx.fillStyle = '#ffffff';
        ctx.fill();
        ctx.restore();
      };
      if (state && state.sgfMoves && state.currentMoveIndex >= 0) {
        var idx = state.currentMoveIndex;
        var move = state.sgfMoves[idx];
        if (move && move.c != null && move.r != null) {
          var vertex = [move.c, move.r];
          var sign = move.player === 'B' ? 1 : -1;
          var prevBoard = getBoardBeforeMove(idx);
          var atariedStones = getAtariedStones(prevBoard, sign, vertex);
          for (var k = 0; k < atariedStones.length; k++) {
            var stone = atariedStones[k];
            var scoords = getVisualCoords(stone[0], stone[1], PADDING, CELL_SIZE);
            _drawCautionTriangle(ctx, scoords.cx, scoords.cy, CELL_SIZE);
          }
        }
      }
    }
  }
};

var EMPTY_ROW = function() { return {player: null, annotation: null, label: null} }

var boardToIntArray = function(board) {
  var h = board.length, w = h === 0 ? 0 : board[0].length
  var data = []
  for (var y = 0; y < h; y++) {
    var row = []
    for (var x = 0; x < w; x++) {
      var cell = board[y][x]
      row.push(cell && cell.player === 'B' ? 1 : cell && cell.player === 'W' ? -1 : 0)
    }
    data.push(row)
  }
  return data
}

var getZone = function(c, r) {
  var isLeft = c < 6;
  var isRight = c > 12;
  var isTop = r < 6;
  var isBottom = r > 12;
  
  if (isLeft && isTop) return "Top-Left Corner";
  if (isRight && isTop) return "Top-Right Corner";
  if (isLeft && isBottom) return "Bottom-Left Corner";
  if (isRight && isBottom) return "Bottom-Right Corner";
  
  if (isLeft) return "Left Side";
  if (isRight) return "Right Side";
  if (isTop) return "Top Side";
  if (isBottom) return "Bottom Side";
  
  return "Center";
};

var areZonesAdjacent = function(z1, z2) {
  if (z1 === z2) return true;
  if (z1 === "Center" || z2 === "Center") return true;
  
  var adj = {
    "Top Side": ["Top-Left Corner", "Top-Right Corner"],
    "Bottom Side": ["Bottom-Left Corner", "Bottom-Right Corner"],
    "Left Side": ["Top-Left Corner", "Bottom-Left Corner"],
    "Right Side": ["Top-Right Corner", "Bottom-Right Corner"],
    "Top-Left Corner": ["Top Side", "Left Side"],
    "Top-Right Corner": ["Top Side", "Right Side"],
    "Bottom-Left Corner": ["Bottom Side", "Left Side"],
    "Bottom-Right Corner": ["Bottom Side", "Right Side"]
  };
  
  var list = adj[z1];
  if (list && list.indexOf(z2) !== -1) return true;
  return false;
};

var manhattanDist = function(c1, r1, c2, r2) {
  return Math.abs(c1 - c2) + Math.abs(r1 - r2);
};

var getConnectedComponent = function(board, startC, startR, color) {
  var component = new Set();
  var queue = [{c: startC, r: startR}];
  var dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  
  while (queue.length > 0) {
    var curr = queue.shift();
    var key = curr.c + ',' + curr.r;
    if (component.has(key)) continue;
    component.add(key);
    
    for (var i = 0; i < dirs.length; i++) {
      var nc = curr.c + dirs[i][0];
      var nr = curr.r + dirs[i][1];
      if (nc >= 0 && nc < 19 && nr >= 0 && nr < 19) {
        var cell = board[nr][nc];
        if (cell && cell.player === color) {
          if (!component.has(nc + ',' + nr)) {
            queue.push({c: nc, r: nr});
          }
        }
      }
    }
  }
  return component;
};

var getVirtualComponent = function(board, startC, startR, color) {
  var component = new Set();
  var queue = [{c: startC, r: startR, depth: 0}];
  
  while (queue.length > 0) {
    var curr = queue.shift();
    var key = curr.c + ',' + curr.r;
    if (component.has(key)) continue;
    component.add(key);
    
    if (curr.depth >= 5) continue;
    
    for (var nr = 0; nr < 19; nr++) {
      for (var nc = 0; nc < 19; nc++) {
        var cell = board[nr][nc];
        if (cell && cell.player === color) {
          var dist = Math.abs(curr.c - nc) + Math.abs(curr.r - nr);
          if (dist <= 3) {
            var newKey = nc + ',' + nr;
            if (!component.has(newKey)) {
              queue.push({c: nc, r: nr, depth: curr.depth + 1});
            }
          }
        }
      }
    }
  }
  return component;
};

var interactsLocally = function(board, currC, currR, targetC, targetR, player) {
  // Pass moves are stored with r=c=-1; indexing board[-1] would throw.
  if (currC < 0 || currR < 0 || targetC < 0 || targetR < 0) return false;
  var opponentColor = player === 'B' ? 'W' : 'B';
  var dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  
  var targetCell = board[targetR][targetC];
  if (!targetCell || targetCell.player !== opponentColor) return false;
  
  var virtualComp = getVirtualComponent(board, targetC, targetR, opponentColor);
  
  for (var i = 0; i < dirs.length; i++) {
    var nc = currC + dirs[i][0];
    var nr = currR + dirs[i][1];
    if (nc >= 0 && nc < 19 && nr >= 0 && nr < 19) {
      var cell = board[nr][nc];
      if (cell && cell.player === opponentColor) {
        var key = nc + ',' + nr;
        if (virtualComp.has(key)) {
          return true;
        }
      }
    }
  }
  return false;
};

var hasUrgentAtari = function(board, color, prevC, prevR) {
  var dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  for (var i = 0; i < dirs.length; i++) {
    var nc = prevC + dirs[i][0];
    var nr = prevR + dirs[i][1];
    if (nc >= 0 && nc < 19 && nr >= 0 && nr < 19) {
      if (board[nr] && board[nr][nc] && board[nr][nc].player === color) {
        var visited = new Set();
        var queue = [{c: nc, r: nr}];
        var stringStones = new Set();
        var liberties = new Set();
        
        while (queue.length > 0) {
          var curr = queue.shift();
          var key = curr.c + ',' + curr.r;
          if (stringStones.has(key)) continue;
          stringStones.add(key);
          
          for (var j = 0; j < dirs.length; j++) {
            var nnc = curr.c + dirs[j][0];
            var nnr = curr.r + dirs[j][1];
            if (nnc >= 0 && nnc < 19 && nnr >= 0 && nnr < 19) {
              var nkey = nnc + ',' + nnr;
              var nCell = board[nnr][nnc];
              if (!nCell || !nCell.player) {
                liberties.add(nkey);
              } else if (nCell.player === color && !stringStones.has(nkey)) {
                queue.push({c: nnc, r: nnr});
              }
            }
          }
        }
        if (liberties.size <= 1) return true;
      }
    }
  }
  return false;
};

var getSkirmishStart = function(currIdx, allMoves, boardBeforeCurr) {
  var localIndices = [currIdx];
  var searchStart = Math.max(0, currIdx - 6);
  
  for (var i = currIdx - 1; i >= searchStart; i--) {
    var moveI = allMoves[i];
    if (!moveI || moveI.c == null || moveI.r == null) continue;
    
    var interacts = false;
    for (var j = 0; j < localIndices.length; j++) {
      var refIdx = localIndices[j];
      var moveRef = allMoves[refIdx];
      if (!moveRef || moveRef.c == null || moveRef.r == null) continue;
      
      var dist = manhattanDist(moveI.c, moveI.r, moveRef.c, moveRef.r);
      var virtInteract = interactsLocally(boardBeforeCurr, moveI.c, moveI.r, moveRef.c, moveRef.r, moveRef.player);
      
      if (dist <= 5 || virtInteract) {
        interacts = true;
        break;
      }
    }
    
    if (interacts) {
      localIndices.push(i);
    }
  }
  
  var targetIdx = -1;
  for (var k = 0; k < localIndices.length; k++) {
    var idx = localIndices[k];
    if (idx < currIdx - 1) {
      if (idx > targetIdx) {
        targetIdx = idx;
      }
    }
  }
  
  if (targetIdx !== -1) {
    return targetIdx;
  }
  return currIdx - 1;
};

var evaluateTenuki = function(currC, currR, player, prevMove, boardBeforeCurr, allMoves, currIdx) {
  if (!prevMove || prevMove.c == null || prevMove.r == null) return null;
  if (currC < 0 || currR < 0 || prevMove.c < 0 || prevMove.r < 0) return null; // passes
  
  var currZone = getZone(currC, currR);
  var prevZone = getZone(prevMove.c, prevMove.r);
  
  var dist = manhattanDist(currC, currR, prevMove.c, prevMove.r);
  var zonesAdj = areZonesAdjacent(currZone, prevZone);
  var interactsWithPrev = false;
  if (zonesAdj) {
    interactsWithPrev = interactsLocally(boardBeforeCurr, currC, currR, prevMove.c, prevMove.r, player);
  }
  
  if (dist < 5 || interactsWithPrev) {
    if (dist >= 5) {
      var skirmishStartIdx = getSkirmishStart(currIdx, allMoves, boardBeforeCurr);
      if (skirmishStartIdx !== currIdx - 1) {
        return {
          classString: "Part of the Move " + (skirmishStartIdx + 1) + " skirmish",
          responseVertex: [allMoves[skirmishStartIdx].c, allMoves[skirmishStartIdx].r]
        };
      }
    }
    return null;
  }
  
  var foundLocalFriendly = false;
  var searchDepth = Math.max(0, currIdx - 5);
  for (var i = currIdx - 2; i >= searchDepth; i--) {
    var earlierMove = allMoves[i];
    if (earlierMove && earlierMove.c != null && earlierMove.r != null) {
      var earlierZone = getZone(earlierMove.c, earlierMove.r);
      if (areZonesAdjacent(currZone, earlierZone)) {
        var earlierDist = manhattanDist(currC, currR, earlierMove.c, earlierMove.r);
        var interactsWithEarlier = interactsLocally(boardBeforeCurr, currC, currR, earlierMove.c, earlierMove.r, player);
        
        if (earlierDist < 5 || interactsWithEarlier) {
          if (earlierMove.player !== player) {
            return {
              classString: "Local Response to Move " + (i + 1),
              responseVertex: [earlierMove.c, earlierMove.r]
            };
          } else {
            foundLocalFriendly = true;
          }
        }
      }
    }
  }
  
  if (foundLocalFriendly) {
    return null;
  }
  
  if (dist < 5) {
    return { classString: "Local Shift" };
  }
  
  var currZone = getZone(currC, currR);
  var prevZone = getZone(prevMove.c, prevMove.r);
  
  var isGlobalShift = (currZone !== prevZone || Math.abs(currC - prevMove.c) >= 6 || Math.abs(currR - prevMove.r) >= 6);
  
  var isSente = false;
  var hasNextMove = false;
  if (currIdx + 1 < allMoves.length) {
    var nextMove = allMoves[currIdx + 1];
    if (nextMove && nextMove.c != null && nextMove.r != null && nextMove.c >= 0 && nextMove.r >= 0) {
      hasNextMove = true;
      
      var boardBeforeNext = JSON.parse(JSON.stringify(boardBeforeCurr));
      if (typeof playStoneWithCaptures === 'function') {
        playStoneWithCaptures(boardBeforeNext, currR, currC, player);
      } else if (typeof window.playStoneWithCaptures === 'function') {
        window.playStoneWithCaptures(boardBeforeNext, currR, currC, player);
      }
      
      var nextDist = manhattanDist(nextMove.c, nextMove.r, currC, currR);
      var nextZone = getZone(nextMove.c, nextMove.r);
      var nextZonesAdj = areZonesAdjacent(nextZone, currZone);
      
      var nextInteracts = false;
      if (nextZonesAdj) {
        nextInteracts = interactsLocally(boardBeforeNext, nextMove.c, nextMove.r, currC, currR, nextMove.player);
      }
      
      if (nextDist < 5 || nextInteracts) {
        isSente = true;
      }
    }
  }
  
  var senteGoteSuffix = null;
  if (hasNextMove) {
    senteGoteSuffix = isSente ? " (sente)" : " (gote)";
  }
  
  if (isGlobalShift) {
    if (hasUrgentAtari(boardBeforeCurr, player, prevMove.c, prevMove.r)) {
      return { classString: "Tenuki (Blunder - Ignored Urgent Atari)", responseVertex: [prevMove.c, prevMove.r] };
    }
    return { classString: "Tenuki" + (senteGoteSuffix !== null ? senteGoteSuffix : " (Strategic Global Shift)") };
  } else {
    return { classString: "Tenuki" + (senteGoteSuffix !== null ? senteGoteSuffix : " (Same Sector, Distant)") };
  }
};

var getBoardBeforeMove = function(moveIndex) {
  var state = window.state;
  var board = Array.from({length: 19}, function() { return Array.from({length: 19}, EMPTY_ROW) })
  if (!state) return board

  var baseline = state.baselineBoard
  if (baseline) {
    board = JSON.parse(JSON.stringify(baseline))
  }

  var moves = state.sgfMoves || []
  for (var i = 0; i < moveIndex && i < moves.length; i++) {
    var m = moves[i]
    if (m && m.player && m.c != null && m.r != null && typeof playStoneWithCaptures === 'function') {
      playStoneWithCaptures(board, m.r, m.c, m.player)
    }
  }
  return board
}

var detectCurrentMoveTerm = function() {
  var state = window.state;
  if (!state) return null
  var moves = state.sgfMoves || []
  var idx = state.currentMoveIndex
  if (idx < 0 || idx >= moves.length) return null

  var move = moves[idx]
  if (!move || !move.player || move.c == null || move.r == null) return null

  var prevBoard = getBoardBeforeMove(idx)
  var data = boardToIntArray(prevBoard)
  var sign = move.player === 'B' ? 1 : -1
  var vertex = [move.c, move.r]
  var patternMatch = findPatternInMove(data, sign, vertex)
  
  var prevMove = idx > 0 ? moves[idx - 1] : null;
  var tenukiResult = evaluateTenuki(move.c, move.r, move.player, prevMove, prevBoard, moves, idx);
  
  var greenVertices = [];
  
  if (tenukiResult) {
    if (!patternMatch || !patternMatch.pattern || !patternMatch.pattern.name) {
      patternMatch = { pattern: { name: tenukiResult.classString, url: null }, match: {} };
    } else {
      var newMatch = JSON.parse(JSON.stringify(patternMatch));
      newMatch.pattern.name = newMatch.pattern.name + " : " + tenukiResult.classString;
      patternMatch = newMatch;
    }
    if (tenukiResult.responseVertex) {
      greenVertices = [tenukiResult.responseVertex];
    }
  }

  var blueVertices = getMatchedVertices(patternMatch)
  return { patternMatch: patternMatch, blueVertices: blueVertices, greenVertices: greenVertices }
}

window.detectHypotheticalTerm = function(r, c, player, moveIdx) {
  var state = window.state;
  if (!state) return null
  var prevBoard = getBoardBeforeMove(moveIdx < 0 ? 0 : moveIdx)
  var data = boardToIntArray(prevBoard)
  var sign = player === 'B' ? 1 : -1
  var vertex = [c, r]
  var patternMatch = findPatternInMove(data, sign, vertex)
  
  var moves = state.sgfMoves || []
  var actualIdx = moveIdx < 0 ? 0 : moveIdx;
  var prevMove = moves[actualIdx];
  var tenukiResult = evaluateTenuki(c, r, player, prevMove, prevBoard, moves, actualIdx + 1);
  
  var greenVertices = [];
  
  if (tenukiResult) {
    if (!patternMatch || !patternMatch.pattern || !patternMatch.pattern.name) {
      patternMatch = { pattern: { name: tenukiResult.classString, url: null }, match: {} };
    } else {
      var newMatch = JSON.parse(JSON.stringify(patternMatch));
      newMatch.pattern.name = newMatch.pattern.name + " : " + tenukiResult.classString;
      patternMatch = newMatch;
    }
    if (tenukiResult.responseVertex) {
      greenVertices = [tenukiResult.responseVertex];
    }
  }
  var blueVertices = getMatchedVertices(patternMatch)
  return { patternMatch: patternMatch, blueVertices: blueVertices, greenVertices: greenVertices }
}

var getMatchedVertices = function(patternMatch) {
  var state = window.state;
  if (!patternMatch) return []
  var anchors = patternMatch.match.anchors || []
  var vertices = patternMatch.match.vertices || []
  var all = [].concat(anchors, vertices)

  var nextBoard = getBoardBeforeMove(state.currentMoveIndex + 1)
  return all.filter(function(v) {
    var y = v[1], x = v[0]
    return nextBoard[y] && nextBoard[y][x] && nextBoard[y][x].player !== null
  })
}

// ═══════ 5. BADGE UI ═══════════════════════════════════════════

var _badgeB = null
var _badgeW = null
var _badgeRow = null

var makeBadgeEl = function() {
  var b = document.createElement('span')
  b.style.display = 'none'
  b.title = 'Go term detected for this move'
  b.addEventListener('mouseenter', function() { _termHL.show() })
  b.addEventListener('mouseleave', function() { _termHL.hide(); })
  b.addEventListener('click', function(e) {
    e.preventDefault()
    if (_termHL.url)
      window.open(_termHL.url, '_blank')
  })
  return b
}

var ensureBadgeRow = function() {
  if (_badgeRow) return
  var wrapper = document.getElementById('sgf-meta-wrapper')
  if (!wrapper) return

  var row = document.createElement('div')
  row.id = 'move-term-row'
  row.style.cssText = 'display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:80px;width:100%;margin-top:8px'

  _badgeB = makeBadgeEl()
  _badgeB.id = 'move-term-badge-b'

  _badgeW = makeBadgeEl()
  _badgeW.id = 'move-term-badge-w'

  var left = document.createElement('div')
  left.style.cssText = 'display:flex;justify-content:flex-end'
  left.appendChild(_badgeB)

  var center = document.createElement('div')
  center.style.cssText = 'display:flex;justify-content:center'

  var right = document.createElement('div')
  right.style.cssText = 'display:flex;justify-content:flex-start'
  right.appendChild(_badgeW)

  wrapper.appendChild(row)
  row.appendChild(left)
  row.appendChild(center)
  row.appendChild(right)

  _badgeRow = row
}

var updateBadge = function(patternMatch, vertices, greenVertices) {
  var state = window.state;
  ensureBadgeRow()
  if (!_badgeB || !_badgeW) return

  // Store for global refresh if needed
  if (patternMatch !== undefined) {
    _termHL.set(vertices || [], greenVertices || [], patternMatch ? patternMatch.pattern.name : '', patternMatch ? patternMatch.pattern.url : null);
  } else {
    patternMatch = _termHL.name ? { pattern: { name: _termHL.name, url: _termHL.url } } : null;
    vertices = _termHL.blue;
    greenVertices = _termHL.green;
  }

  // Which player made the current move?
  var currentPlayer = null
  if (typeof state !== 'undefined' && state) {
    var idx = state.currentMoveIndex
    if (idx >= 0 && state.sgfMoves && idx < state.sgfMoves.length)
      currentPlayer = state.sgfMoves[idx].player
  }

  if (!patternMatch || !currentPlayer) {
    _badgeB.style.display = 'none'
    _badgeW.style.display = 'none'
    _termHL.clear()
    if (_termVisible && typeof drawBoard === 'function') drawBoard()

    // Hide Study Mode opponent term UI
    var studyOpponentContainer = document.getElementById('study-opponent-term-container');
    if (studyOpponentContainer) {
      studyOpponentContainer.style.visibility = 'hidden';
    }

    return
  }

  _termHL.set(vertices || [], greenVertices || [], patternMatch.pattern.name, patternMatch.pattern.url);

  // Auto-show highlights when info toggle is active
  if (_termVisible) _termHL.show();

  var name = patternMatch.pattern.name
  var isBlack = currentPlayer === 'B'
  // When POV is flipped, Black's name is on the right — swap badge side
  var isFlipped = state && state.isPovFlipped || false
  var showLeft = (isBlack && !isFlipped) || (!isBlack && isFlipped)
  var active = showLeft ? _badgeB : _badgeW
  var inactive = showLeft ? _badgeW : _badgeB

  active.textContent = name
  active.style.display = 'inline-block'
  if (!_termVisible) active.style.display = 'none'
  active.title = 'Click to view "' + name + '" on Sensei\'s Library'
  
  if (isBlack) {
    active.classList.add('badge-black-color')
    active.classList.remove('badge-white-color')
  } else {
    active.classList.add('badge-white-color')
    active.classList.remove('badge-black-color')
  }

    inactive.style.display = 'none'

  // +N overlaid at the right edge of the term row
  ;(function showCapturePopup() {
    var banner = document.getElementById('study-player-term-banner')
    if (!banner) return
    var captures = (typeof state !== 'undefined' && state && state.captures) ? state.captures.lastCaptured : 0
    if (captures <= 0) return

    var old = document.getElementById('term-capture-popup')
    if (old && old.parentNode) old.parentNode.removeChild(old)

    var popup = document.createElement('span')
    popup.id = 'term-capture-popup'
    popup.textContent = '+' + captures
    popup.style.cssText = 'position:absolute;right:8px;bottom:6px;font-size:24px;font-weight:bold;color:#22c55e;opacity:0;pointer-events:none;z-index:20;font-family:\"Anthropic Sans Bold\",sans-serif;text-shadow:0 1px 4px rgba(0,0,0,0.2);transition:opacity 0.2s ease-in;'
    banner.appendChild(popup)
    requestAnimationFrame(function() { popup.style.opacity = '1' })
    setTimeout(function() { popup.style.transition = 'opacity 0.8s ease-out'; popup.style.opacity = '0' }, 700)
    setTimeout(function() { if (popup.parentNode) popup.parentNode.removeChild(popup) }, 1500)
  })()

  // Update Study Mode UI if it exists
  var studyOpponentContainer = document.getElementById('study-opponent-term-container');
  var studyOpponentTerm = document.getElementById('study-opponent-term');
  var studyOpponentName = document.getElementById('study-opponent-name');
  if (studyOpponentContainer && studyOpponentTerm && studyOpponentName) {
      if (patternMatch) {
          studyOpponentContainer.style.visibility = 'visible';
          studyOpponentTerm.textContent = name;
          
          var bName = (state && state.sgfMetadata && state.sgfMetadata.pb) ? state.sgfMetadata.pb : 'Black';
          var wName = (state && state.sgfMetadata && state.sgfMetadata.pw) ? state.sgfMetadata.pw : 'White';
          
          var formatStudyPlayerName = function(name) {
              if (!name) return name;
              var parts = name.trim().split(/\s+/);
              if (parts.length > 1) {
                  var lastWord = parts[parts.length - 1];
                  var firstLetter = parts[0].charAt(0).toUpperCase();
                  return lastWord + ', ' + firstLetter + '.';
              }
              return name;
          };
          
          if (isBlack) {
              // The term was played by Black, so Black is the opponent
              studyOpponentName.textContent = formatStudyPlayerName(bName) + ':';
              studyOpponentTerm.style.backgroundColor = '#FFD101';
              studyOpponentTerm.style.color = '#000000';
              studyOpponentTerm.style.borderColor = 'transparent';
              studyOpponentTerm.className = 'study-term-b';
          } else {
              // The term was played by White, so White is the opponent
              studyOpponentName.textContent = formatStudyPlayerName(wName) + ':';
              studyOpponentTerm.style.backgroundColor = '#101389';
              studyOpponentTerm.style.color = '#faf7ef';
              studyOpponentTerm.style.borderColor = 'transparent';
              studyOpponentTerm.className = 'study-term-w';
          }

          if (!studyOpponentTerm._hoverBound) {
              studyOpponentTerm.addEventListener('mouseenter', function() { _termHL.show(); });
              studyOpponentTerm.addEventListener('mouseleave', function() { _termHL.hide(); });
              studyOpponentTerm.addEventListener('click', function(e) {
                e.preventDefault();
                if (_termHL.url)
                  window.open(_termHL.url, '_blank');
              });
              studyOpponentTerm._hoverBound = true;
          }
      } else {
          studyOpponentContainer.style.visibility = 'hidden';
      }
  }

  // Info toggle override
  if (!_termVisible && studyOpponentContainer) {
      studyOpponentContainer.style.visibility = 'hidden';
  }
}

// ═══════ 6. CANVAS HIGHLIGHTING ═══════════════════════════════

var getCanvasCtxs = function() {
  var ctxs = [];
  try {
    if (typeof elements !== 'undefined') {
      if (elements.canvasInitial) {
        var size = (typeof state !== 'undefined' && state.initialBoardStyle && state.initialBoardStyle.board && state.initialBoardStyle.board.size) ? state.initialBoardStyle.board.size : 600;
        ctxs.push({ ctx: elements.canvasInitial.getContext('2d'), scale: size / 600 });
      }
      if (elements.canvasStudy) {
        var size = (typeof state !== 'undefined' && state.studyBoardStyle && state.studyBoardStyle.board && state.studyBoardStyle.board.size) ? state.studyBoardStyle.board.size : 600;
        ctxs.push({ ctx: elements.canvasStudy.getContext('2d'), scale: size / 600 });
      }
    }
  } catch(e) {}
  
  if (ctxs.length === 0) {
    var canvas = document.getElementById('go-board-canvas') || 
                 document.getElementById('go-board-canvas-initial');
    if (canvas) ctxs.push({ ctx: canvas.getContext('2d'), scale: 1.0 });
  }
  return ctxs;
}

var COLS = ['A','B','C','D','E','F','G','H','J','K','L','M','N','O','P','Q','R','S','T']

window.drawMoveTermHighlights = function(ctx, PADDING, CELL_SIZE) { _termHL.drawBottom(ctx, PADDING, CELL_SIZE); };

window.drawMoveTermTopHighlights = function(ctx, PADDING, CELL_SIZE) { _termHL.drawTop(ctx, PADDING, CELL_SIZE); };

window.getStoneRadiusForHighlight = function(CELL_SIZE, player) {
  var state = window.state;
  var STONE_R = CELL_SIZE * 0.47;
  if (state) {
    var style = document.body.classList.contains('study-mode-active') ? state.studyBoardStyle : state.initialBoardStyle;
    var stoneStyle = player === 'W' ? (style && style.whiteStone) : (style && style.blackStone);
    if (stoneStyle && stoneStyle.bgSize !== undefined) {
      var bgSizeVal = parseFloat(stoneStyle.bgSize);
      if (!isNaN(bgSizeVal)) {
        if (bgSizeVal <= 2.0) STONE_R = bgSizeVal * CELL_SIZE;
        else STONE_R = bgSizeVal * (CELL_SIZE / 29.3333);
      }
    }
  }
  return STONE_R;
};

var getVisualCoords = function(col, row, PADDING, CELL_SIZE) {
  return {
    cx: PADDING + col * CELL_SIZE,
    cy: PADDING + row * CELL_SIZE
  };
};

var getAtariedStones = function(boardBefore, sign, vertex) {
  if (!boardBefore || !vertex) return [];
  var h = boardBefore.length, w = h === 0 ? 0 : boardBefore[0].length;
  var x = vertex[0], y = vertex[1];
  var data = boardToIntArray(boardBefore);
  var neighbors = getNeighbors(vertex, w, h);
  var opponentColor = sign === 1 ? 'W' : 'B';
  
  var atariedStones = [];
  var seenKeys = new Set();
  
  for (var i = 0; i < neighbors.length; i++) {
    var nx = neighbors[i][0], ny = neighbors[i][1];
    if (data[ny][nx] !== -sign) continue;
    
    var lc = getPseudoLibertyCount([nx, ny], data);
    // If liberty count before this move was exactly 2, 
    // then playing at the vertex puts this group in Atari!
    if (lc === 2) {
      var comp = getConnectedComponent(boardBefore, nx, ny, opponentColor);
      comp.forEach(function(key) {
        if (!seenKeys.has(key)) {
          seenKeys.add(key);
          var parts = key.split(',');
          atariedStones.push([parseInt(parts[0], 10), parseInt(parts[1], 10)]);
        }
      });
    }
  }
  return atariedStones;
};

var _clearHighlights = function() { _termHL.clear(); if (typeof drawBoard === 'function') drawBoard(); }

var _lastMoveIndex = -1

// ═══════ 7. REACTIVITY ════════════════════════════════════════

var onMoveChanged = function() {
  var state = window.state;
  if (!state) return
  var idx = state.currentMoveIndex
  if (idx === _lastMoveIndex) return
  _lastMoveIndex = idx

  _termHL.clear()

  var result = detectCurrentMoveTerm()
  if (!result) {
    updateBadge(null)
    return
  }

  updateBadge(result.patternMatch, result.blueVertices, result.greenVertices)
}

var pollTimer = null

var startPolling = function() {
  if (pollTimer) return
  pollTimer = setInterval(function() {
    var state = window.state;
    if (!state) return
    onMoveChanged()
  }, 300)
}

// Hook into goToMove for immediate detection on navigation
var _hookGoToMove = function() {
  if (typeof goToMove !== 'function') return
  var orig = goToMove
  goToMove = function(index) {
    orig(index)
    onMoveChanged()
  }
}

// Hook into flipBoard180 to re-detect after board flip
var _hookFlipBoard = function() {
  if (typeof flipBoard180 !== 'function') return
  var orig = flipBoard180
  flipBoard180 = function() {
    orig()
    _clearHighlights()
    _lastMoveIndex = -1
    setTimeout(onMoveChanged, 50)
  }
}

